SELECT p.id AS product_id, p.name,p.grade,p.charge_name AS productChargeName, pi.project_status,p.brand_name,p.type,pi.id AS projectId,p.grade_id, p.charge_id AS productChargeId,pi.charge_id AS projectChargeId, p.approval_status,pi.charge_name AS projectChargeName ,pi.end_time, pi.create_time FROM product_info p INNER JOIN project_info pi ON p.id=pi.product_id WHERE P.delete_state=0 AND p.is_finished_product_dev = 1
AND P.category_id=#{params.categoryId}
AND (P.name LIKE concat('%',#{params.searchKeyword},'%') OR p.id IN (SELECT pd.product_id FROM product_detail pd WHERE pd.sku_no LIKE concat('%',#{params.searchKeyword},'%')) OR p.spu_no LIKE concat('%',#{params.searchKeyword},'%'))
AND pi.project_status IN
#{state}
AND P.id IN
#{productId}
AND p.id NOT IN
#{productId}
AND p.id IN (SELECT pt.product_id FROM project_task pt WHERE 1 = 1 ${params.param})
ORDER BY pi.create_time DESC

